UNIT="xb-lock-first-hop"
PARENT=Path("/sys/fs/cgroup/xiongbaowork.slice")
KEYS=("memory.max","memory.swap.max","memory.oom.group")
def gates():
    return {n:(PARENT/n).read_text().strip() for n in KEYS}
def restore():
    if PARENT.exists():
        for n,v in zip(KEYS,["536870912","0","1"]):(PARENT/n).write_text(v)
        assert gates()==dict(zip(KEYS,["536870912","0","1"]))
def main():
    assert os.geteuid()==0
    uid,gid=int(sys.argv[1]),int(sys.argv[2])
    assert uid!=0 and gid!=0
    with Path("/run/systemd/system/xiongbaowork.slice").open("x") as out:
        out.write("[Unit]\nDescription=Single locked URL first-hop header probe\n[Slice]\nMemoryMax=512M\nMemorySwapMax=0\n")
    subprocess.run(["systemctl","daemon-reload"],timeout=10,check=True)
    subprocess.run(["systemctl","start","xiongbaowork.slice"],timeout=10,check=True)
    restore()
    deadline=time.monotonic()+40
